CREATE TABLE character_equipment (character_id TEXT NOT NULL REFERENCES characters(id), slot_key TEXT NOT NULL CHECK(slot_key IN ('charm','ear1','head','face','ear2','neck','shoulders','arms','back','wrist1','wrist2','ranged','hands','primary','secondary','finger1','finger2','chest','legs','feet','waist','powerSource','ammo')), item_id INTEGER REFERENCES item_references(item_id), source TEXT CHECK(source IN ('award','reference')), updated_at TEXT NOT NULL, updated_by TEXT NOT NULL REFERENCES users(id), operation_id TEXT NOT NULL UNIQUE, PRIMARY KEY(character_id,slot_key), CHECK((item_id IS NULL AND source IS NULL) OR (item_id IS NOT NULL AND source IS NOT NULL)));
